#!/usr/bin/env python3
"""
apply_simphony_loto_fix.py

Simphony(https://github.com/fballestermacia/simphony)의 LO-TO 처리를 수정하는
단일 패치 스크립트.

사용법:
    cd <simphony 저장소 루트>          # src/ 가 보이는 위치
    python3 apply_simphony_loto_fix.py
    cd src && make clean && make       # module.f90이 바뀌므로 clean 필수

검증된 기준 (orthorhombic polar HfO2, phonopy 유래 hr.dat):
    - 벌크 밴드가 phonopy 자체 Gonze NAC 계산과 전 경로에서 최대 3.4e-7 THz 일치
      (패치 전 0.2475 THz)
    - Gamma에서 acoustic 2e-5 THz (패치 전 -0.13 THz)
    - slab 밴드 허수 모드 0개 (패치 전 6개, 최저 -6.43 THz)
    - AgP2 공식 예제 회귀: Gamma 최저 1.260234 THz로 불변

수정 내용
=========
[1] 자기항 에르미트화 누락  (ham_bulk.f90)
    QE rgd_blk(PHonon/PH/rigid.f90)에 있는
        fmtx = (fmtx + TRANSPOSE(fmtx)) / 2.d0
    가 이식 과정에서 빠져 있었음. 결과 dipole 행렬이 비-에르미트가 됨
    (측정된 잔차 0.87, 행렬 크기 17 대비 5%). fnat 누적도 QE와 같이
    exp(zi*arg) -> COS(arg)로 맞춤.

[2] q벡터 인덱스 오류  (ham_bulk.f90, ham_bulk_LOTO)
        q(2) = k(1)*rec_lattice(1,2) + ...   (틀림)
        q(2) = k(1)*rec_lattice(2,1) + ...   (맞음)
    같은 파일 77~79행에 올바른 판본이 이미 존재하는 복사-붙여넣기 실수.
    rec_lattice가 비대칭인 저대칭 물질에서만 크게 드러나므로 고대칭 예제
    (AgP2, Al2ZnTe4)에서는 보이지 않았음.

[3] phonopy 호환 Gonze 분할  (신규 gonze_nac.f90, LOTO_method)
    hr.dat에서 뺀 장거리항과 다시 더하는 항의 Ewald 분할이 같아야 상쇄됨.
    phonopy(c/dynmat.c)와 QE 계보는 세 가지가 다름:
      - 구조 위상이 G만 사용(C-type). QE는 G+q(D-type)
      - Lambda를 셀과 G 컷오프에서 유도
      - dd_q0에 (alpha,beta) 에르미트 대칭화 단계가 있음
    phonopy 알고리즘을 Fortran으로 이식하고 LOTO_method='phonopy'로 선택.
    기본값 'qe'는 기존 동작 그대로라 QE2TBDAT 워크플로우에 영향 없음.

[4] Gamma 방향의 k점 순서/MPI 의존성  (module/readinput/ek_bulk/ek_slab)
    keps가 선언부 초기화로 암묵적 SAVE가 되어 "직전에 처리한 k점" 방향을
    재사용. k점은 do ik = 1+cpuid, knv3, num_cpu 로 랭크별 분산되므로
    mpirun -np N의 N에 따라 Gamma 결과가 바뀌었음.
    phonopy(phonon/band_structure.py)와 같이 밴드 경로 구간 자체의 방향을
    쓰도록 변경. 경로가 없는 계산은 LOTO_qdir(기본 1,1,1)로 대체.

[5] Gamma 비해석항 이중 계산  (ham_bulk.f90, ham_qlayer2qlayer.f90)
    gonze 경로는 비해석 q->0 항을 내부에 포함하므로, QE 규약의 별도 항을
    그 위에 더하면 중복됨. LOTO_method='phonopy'일 때 해당 블록을 건너뜀.

[6] slab 장거리항 이중 계산  (ham_qlayer2qlayer.f90)  <- slab 최대 원인
    ek_slab이 논문 Eq.(20)대로 HmnR += D^LR(R)로 실공간에서 넣어두는데,
    ham_qlayer2qlayer*_LOTO가 같은 항을 per-k nac_correction으로 한 번 더
    더하고 있었음. 원본 코드부터 존재하던 버그.

[7] 전역 상태 제거  (module/ek_slab/ek_ribbon/fermiarc/surfstat/ek_bulk)
    added_LR_in_Real_Space 플래그로 공유 HmnR을 변형했다가 되돌리는 구조라
    한 실행 안에서 계산 순서에 따라 결과가 달라졌음. 장거리항을 별도 배열
    HmnR_LRslab에 담고 HmnR은 건드리지 않도록 변경.

부수적으로 노출되는 입력 (모두 기본값이 기존 동작):
    LOTO_method     : 'qe'(기본) / 'phonopy'
    LOTO_qdir       : 경로가 없는 계산에서 Gamma 방향 (기본 1,1,1)
    LOTO_alph       : Ewald 분할 파라미터 (기본 1.0)
    LOTO_gmax       : G 합 컷오프 (기본 14.0)
    LOTO_2D         : slab용 2D 형식 (기본 F). 2*pi 누락은 고쳤으나
                      Sohier 공식은 진공 분리 단일층 전제라 bulk hr.dat에서
                      잘라 만든 두꺼운 slab에는 권장하지 않음.
    LOTO_gamma_offset : Gamma를 구간 방향으로 미세 이동하는 옛 방식 (기본 0 = 사용 안 함)

주의: LOTO_method='phonopy'를 쓸 때는 Born charge를 전치하지 말 것
      (phonopy2TBDAT 계열 스크립트의 --no-transpose-born).
"""

import base64
import os
import subprocess
import sys

DIFF_B64 = """
"""

GONZE_B64 = """
"""

MAKEFILE_OBJ_OLD = "ham_slab.o ham_bulk.o ek_slab.o"
MAKEFILE_OBJ_NEW = "ham_slab.o ham_bulk.o gonze_nac.o ek_slab.o"


def fail(msg):
    print("[!] " + msg)
    sys.exit(1)


def main():
    if not os.path.isdir("src"):
        fail("simphony 저장소 루트에서 실행하세요 (src/ 디렉토리가 보여야 합니다).")
    if not os.path.isfile(os.path.join("src", "ham_bulk.f90")):
        fail("src/ham_bulk.f90 을 찾을 수 없습니다.")

    gonze_path = os.path.join("src", "gonze_nac.f90")
    if os.path.exists(gonze_path):
        fail("src/gonze_nac.f90 이 이미 있습니다. 패치가 이미 적용된 것으로 보입니다.")

    diff_text = base64.b64decode(DIFF_B64).decode()
    gonze_text = base64.b64decode(GONZE_B64).decode()

    # 1) 소스 패치 (git apply -> 실패 시 patch(1))
    print("[1/3] 소스 패치 적용 중...")
    applied = False
    if os.path.isdir(".git"):
        p = subprocess.run(["git", "apply", "--check", "-"],
                           input=diff_text, text=True,
                           stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        if p.returncode == 0:
            subprocess.run(["git", "apply", "-"], input=diff_text, text=True, check=True)
            applied = True
        else:
            print("    git apply --check 실패:")
            print("    " + p.stderr.strip().replace("\n", "\n    "))
    if not applied:
        p = subprocess.run(["patch", "-p1", "--forward", "--batch"],
                           input=diff_text, text=True,
                           stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        if p.returncode != 0:
            print(p.stdout)
            fail("패치 적용 실패. 저장소가 수정되지 않은 상태인지 확인하세요.")
        applied = True
    print("    완료")

    # 2) 새 소스 파일
    print("[2/3] src/gonze_nac.f90 생성 중...")
    with open(gonze_path, "w") as f:
        f.write(gonze_text)
    print("    완료")

    # 3) Makefile에 오브젝트 추가
    print("[3/3] Makefile 갱신 중...")
    touched = []
    for name in sorted(os.listdir("src")):
        if not name.startswith("Makefile"):
            continue
        path = os.path.join("src", name)
        try:
            text = open(path).read()
        except (IOError, UnicodeDecodeError):
            continue
        if "gonze_nac.o" in text:
            continue
        if MAKEFILE_OBJ_OLD in text:
            open(path, "w").write(text.replace(MAKEFILE_OBJ_OLD, MAKEFILE_OBJ_NEW))
            touched.append(name)
    if touched:
        print("    갱신: " + ", ".join(touched))
    else:
        print("    [!] OBJ 목록을 자동으로 찾지 못했습니다.")
        print("        쓰시는 Makefile의 OBJ에 gonze_nac.o 를 직접 추가하세요.")

    print("")
    print("패치 완료. 이어서:")
    print("    cd src && make clean && make")
    print("  (module.f90이 바뀌었으므로 make clean 은 필수입니다.")
    print("   생략하면 readinput.o가 갱신되지 않아 네임리스트에서")
    print("   'Invalid line in namelist PARAMETERS' 오류가 납니다.)")
    print("")
    print("phonopy 유래 hr.dat을 쓰는 경우 pn.in 의 &PARAMETERS 에:")
    print("    LOTO_method = 'phonopy'")
    print("그리고 Born charge는 전치하지 마세요 (--no-transpose-born).")


if __name__ == "__main__":
    main()
